describe('Login Form Validation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display username required error when both fields are empty', () => {
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="error"]').should('be.visible');
    cy.get('[data-test="error"]').should('contain', 'Username is required');
  });

  it('should display password required error when only username is entered', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="error"]').should('be.visible');
    cy.get('[data-test="error"]').should('contain', 'Password is required');
  });

  it('should clear error message when user starts typing in empty username field', () => {
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="error"]').should('be.visible');
    cy.get('[data-test="username"]').type('a');
    cy.get('[data-test="error"]').should('not.exist');
  });

  it('should display error when password field is empty after entering username', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').click();
    cy.get('[data-test="password"]').blur();
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="error"]').should('contain', 'Password is required');
  });
});
